function applyView(){$('list').style.transform=`translate(${view.x}px, ${view.y}px) scale(${view.scale})`;$('zoom-value').textContent=Math.round(view.scale*100)+'%';}
function resetView(){view.x=0;view.y=0;view.scale=1;applyView();}
function fitAll(){const r=$('canvas').getBoundingClientRect(),nodes=[...($('list').querySelectorAll?.('.project-node')||[])];if(!nodes.length){resetView();return;}const boxes=nodes.map(n=>{const x=Number(n.dataset.x)||0;return {left:x,top:0,right:x+(n.offsetWidth||332),bottom:n.offsetHeight||0};}),fit=C.fitView(boxes,r.width,r.height,20);if(!fit){resetView();return;}view.scale=fit.scale;view.x=fit.x-16;view.y=fit.y-12;applyView();closeDetail(false);}
function zoom(factor,x,y){const r=$('canvas').getBoundingClientRect(),px=x??r.left+r.width/2,py=y??r.top+r.height/2,next=Math.max(.35,Math.min(2,view.scale*factor)),ratio=next/view.scale;view.x=px-r.left-16-(px-r.left-16-view.x)*ratio;view.y=py-r.top-12-(py-r.top-12-view.y)*ratio;view.scale=next;applyView();closeDetail(false);}
