function openDetail(project,task,message,button){closeClassifier(false);closeSources();opener=button;selected={project,taskId:task?.id||'',message:C.messageIdentity(message),date:selectedDate};detailLimit=100;$('whole').checked=false;$('detail').hidden=false;renderDetail();positionFloat($('detail'),button);$('detail-title').focus({preventScroll:true});const target=[...$('detail-messages').children].find(n=>n.dataset.message===selected.message);if(target){const top=target.getBoundingClientRect().top-$('detail-scroll').getBoundingClientRect().top;$('detail-scroll').scrollTop=Math.max(0,$('detail-scroll').scrollTop+top-12);}}
