 $('detail-title').textContent=task?.title||(selected.taskId==='__unclassified__'?'未分类':projectName(selected.project));$('detail-meta').replaceChildren(el('p','',`${messages.length} 条用户消息 · ${$('whole').checked?'全部已收录日期':selected.date}`));if(task){if(task.summary)$('detail-meta').append(el('p','',task.summary));if(task.feature||task.module)$('detail-meta').append(el('p','',[task.feature,task.module].filter(Boolean).join(' · ')));if(task.codeRefs?.length)$('detail-meta').append(el('p','code-refs',task.codeRefs.join(' · ')));}
