 $('classify-start').disabled=!!running||!pending.length||!$('model').value||!$('classify-consent').checked;$('model').disabled=!!running;$('classify-clear').disabled=!!running;$('classify-cancel').hidden=!running;$('classify-cancel').disabled=job?.status==='cancelling';
